ient(to bottom,#fff 78%,#f8fafc 78%);touch-action:none;-webkit-user-select:none;user-select:none}.pdf{display:block;width:100%;height:56vh;border:1px solid #cbd5e1;border-radius:6px;background:#f8fafc}label.check{display:flex;gap:12px;align-items:flex-start;margin:16px 0;line-height:1.45}label.check input{width:22px;height:22px;flex:0 0 22px;margin:0;accent-color:#087b62}.submit-wrap{position:sticky;bottom:0;z-index:5;margin:0 -4px;padding:8px 4px calc(8px + env(safe-area-inset-bottom));background:linear-gradient(to bottom,rgba(255,255,255,0),#fff 18%)}.submit-wrap button{width:100%;box-shadow:0 8px 24px #087b6240}.security{color:#617184;font-size:13px;line-height:1.5}@media(max-width:650px){body{background:#fff}.shell{padding:0 0 calc(10px + env(safe-area-inset-bottom))}.top{padding:calc(15px + env(safe-area-inset-top)) 16px 15px}.top,.card{border-radius:0;margin:0;border-left:0;border-right:0;box-shadow:none}.top h1{font-size:24px;line-height:1.15}.top small{font-size:11px}.top p{font-size:14px;margin-top:4px}.card{padding:16px}.meta{grid-template-columns:1fr 1fr}.meta div{padding:10px}.meta div:last-child{grid-column:1/-1}.meta small{font-size:11px}.meta strong{font-size:14px}.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0}.actions .btn,.actions button{width:100%;padding:11px 8px;text-align:center;font-size:14px}.pdf{height:36vh;min-height:250px;max-height:310px}.signature-box{margin-top:12px}canvas{aspect-ratio:2.15/1}.success{min-height:calc(100svh - env(safe-area-inset-top) - env(safe-area-inset-bottom));padding-top:calc(18px + env(safe-area-inset-top));padding-bottom:calc(18px + env(safe-area-inset-bottom))}.success .actions{grid-template-columns:1fr}.key{font-size:27px;padding:15px 8px;letter-spacing:.04em}.security{margin-bottom:8px}}@media(max-width:650px) and (orientation:landscape){.pdf{height:55vh;max-height:none}canvas{aspect-ratio:3.2/1}.top{padding-top:calc(10px + env(safe-area-inset-top))}}
</style></head><body><main class="shell"><?php if($success):?><section class="card success"><div><h1>Signature enregistrée</h1><p>Transmettez personnellement cette clé à la personne chargée du décaissement :</p><div class="key" id="paymentKey"><?=htmlspecialchars($paymentKey)?></div><p><strong>Point #<?=(int)$link['point_id']?></strong> · clé valable 72 heures</p><div class="actions" style="justify-content:center"><button type="button" id="copyPaymentKey">Copier le code</button><button type="button" id="sharePaymentKey" class="btn secondary">Partager au responsable</button></div><p class="security">Cette clé ouvre uniquement le point signé. Ne la publiez pas dans un groupe et ne l’inscrivez pas sur le document.</p></div></section><?php elseif(!$link):?><section class="card"><h1>Lien indisponible</h1><div class="error"><?=htmlspecialchars($error?:'Ce lien ne peut pas être utilisé.')?></div></section><?php else:?><header class="top"><small>BANAMUR · VALIDATION CONFIDENTIELLE</small><h1>Point quotidien de décaissement</h1><p>Signature personnelle du Directeur Général</p></header><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><section class="card"><div class="meta"><div><small>Point</small><strong>#<?=(int)$link['point_id']?> · Version <?=(int)$link['version_no']?></strong></div><div><small>Date</small><strong><?=htmlspecialchars(date('d/m/Y',strtotime((string)$link['point_date'])))?></strong></div><div><small>Montant</small><strong><?=$money($link['total_amount'])?></strong></div></div><div class="actions"><a class="btn" href="/decaissement/signature_point_jour_pdf.php?token=<?=urlencode($token)?>&mode=inline">Afficher le PDF dans Safari</a><a class="btn secondary" href="/decaissement/signature_point_jour_pdf.php?token=<?=urlencode($token)?>&mode=download">Télécharger le PDF</a></div><div style="border:1px solid #dbe3ec;background:#f8fafc;padding:14px;border-radius:6px"><strong>Consultation sécurisée</strong><p class="security" style="margin-bottom:0">Le PDF s ouvre directement dans le navigateur. Revenez ensuite sur cette page pour signer le point.</p></div></section><form method="post" id="signatureForm" class="card"><input type="hidden" name="token" value="<?=htmlspecialchars($token)?>"><input type="hidden" name="_csrf" value="<?=htmlspecialchars((string)$_SESSION['daily_point_external_csrf'])?>"><input type="hidden" name="signature_data" id="signatureData"><h2>Votre signature pour ce point</h2><p>Cette signature est indépendante de votre profil et ne pourra être utilisée pour aucun autre document.</p><div class="signature-box"><canvas id="signature" width="900" height="360"></canvas></div><div class="actions"><button type="button" id="clear" class="btn secondary">Effacer la signature</button></div><label class="check"><input type="checkbox" name="confirmation" value="1" required><span>Je confirme avoir consulté ce point de décaissement et l’approuver pour la poursuite du circuit.</span></label><div class="submit-wrap"><button type="submit">Signer et obtenir la clé de décaissement</button></div><p class="security">Après validation, le lien devient inutilisable. La date, l’heure et des empreintes techniques de sécurité sont conservées dans le journal d’audit.</p></form><?php endif;?></main><?php if($success):?><script>(()=>{const key=document.getElementById('paymentKey').textContent.trim(),copy=async()=>{try{await navigator.clipboard.writeText(key)}catch(e){const t=document.createElement('textarea');t.value=key;document.body.appendChild(t);t.select();document.execCommand('copy');t.remove()}const b=document.getElementById('copyPaymentKey');b.textContent='Code copié';setTimeout(()=>b.textContent='Copier le code',1800)};document.getElementById('copyPaymentKey').onclick=copy;document.getElementById('sharePaymentKey').onclick=async()=>{const text='Point #<?=(int)$link['point_id']?> autorisé par le DG. Code d’ouverture du décaissement : '+key;if(navigator.share){try{await navigator.share({title:'Autorisation de décaissement BANAMUR',text})}catch(e){}}else await copy()};})();</script><?php elseif($link):?><script>(()=>{const c=document.getElementById('signature'),x=c.getContext('2d');x.lineWidth=3;x.lineCap='round';x.strokeStyle='#10233f';let d=false,w=false;const p=e=>{const r=c.getBoundingClientRect(),q=e.touches?.[0]||e;return{x:(q.clientX-r.left)*c.width/r.width,y:(q.clientY-r.top)*c.height/r.height}};const start=e=>{d=true;w=true;const q=p(e);x.beginPath();x.moveTo(q.x,q.y);e.preventDefault()};const move=e=>{if(!d)return;const q=p(e);x.lineTo(q.x,q.y);x.stroke();e.preventDefault()};['pointerdown','touchstart'].forEach(n=>c.addEventListener(n,start,{passive:false}));['pointermove','touchmove'].forEach(n=>c.addEventListener(n,move,{passive:false}));['pointerup','pointerleave','touchend','touchcancel'].forEach(n=>c.addEventListener(n,()=>d=false));document.getElementById('clear').onclick=()=>{x.clearRect(0,0,c.width,c.height);w=false};document.getElementById('signatureForm').onsubmit=e=>{if(!w){e.preventDefault();alert('Veuillez dessiner votre signature.');return}document.getElementById('signatureData').value=c.toDataURL('image/png')};})();</script><?php endif;?></body></html>

